import {
  Label,
  Slider as AriaSlider,
  SliderFill,
  SliderOutput,
  SliderStateContext,
  SliderThumb,
  SliderTrack,
} from "react-aria-components";
import type { SliderProps as AriaSliderProps } from "react-aria-components";
import { useContext, useId, type CSSProperties, type ReactNode, type Ref } from "react";
import { NumberField } from "./NumberField";
import "./Slider.css";

/**
 * Built-in accessible name for thumb `index` of a `count`-thumb slider.
 *
 * A multi-thumb slider needs a name **per thumb** — the visible `label` names the group, not each
 * handle, and React Aria supplies nothing (its own docs pass `aria-label` to each `SliderThumb`),
 * so without this a range slider's handles announce as unnamed. Overridable via `thumbLabels`;
 * these defaults exist so the accessible name is never *missing*, not to be the final copy.
 */
/** A tick label's rung: one below the `caption-<size>` the slider's description takes. */
const TICK_RUNG = { small: "small", medium: "small", large: "medium" } as const;

function defaultThumbLabel(index: number, count: number) {
  if (index === 0) return "Minimum";
  if (index === count - 1) return "Maximum";
  return `Value ${index + 1}`;
}

export type SliderSize = "small" | "medium" | "large";
/** Where the value sits. `top` is the resting readout; `bubble` rides the thumb instead. */
export type SliderThumbShape = "rectangle" | "circle";
export type SliderValuePlacement = "top" | "start" | "end" | "bubble" | "none";

/**
 * What the readout IS, which is a different question from where it sits.
 *
 * `output` is React Aria's `<output>`: the value, rendered, read-only. `field` replaces it with a
 * `NumberField` per thumb, so the value can be typed as well as dragged.
 *
 * Orthogonal to {@link SliderValuePlacement} on purpose: placement owns WHERE and this owns WHAT,
 * so a field can sit at `top`, `start` or `end`. Folding it into the placement vocabulary would
 * have put a KIND in a list of positions and fixed the field to one end of the track. It has no
 * effect at `bubble` or `none`, which render no readout for it to change; the component ignores
 * it there rather than refusing, the way `tickLabels` with no `ticks` renders nothing.
 */
export type SliderValueControl = "output" | "field";

/* No `data-value-control` attribute, deliberately. `valuePlacement` earns one because it moves the
 * SAME element and the CSS has to select it; this prop changes WHICH element renders, so the
 * element's own class is already the signal and an attribute nothing styles is dead surface. The
 * verify engine agrees and says so: it reported `emitted:value-control (no CSS selector styles it)`
 * as the library's only coverage gap, against a baseline in which no component has an accepted one. */

export interface SliderProps
  extends Omit<AriaSliderProps<number | number[]>, "className" | "children"> {
  /**
   * Size axis: track thickness and thumb.
   *
   * @default "medium"
   */
  size?: SliderSize;
  /**
   * The thumb sits INSIDE a thick track, and the fill runs past it to the track's padding, so the
   * filled part reads as one pill carrying the thumb. Without it the thumb overhangs a thin track.
   *
   * @default false
   */
  isInset?: boolean;
  /**
   * The thumb's outline: `rectangle` a capsule longer along the track, `circle` a round thumb as
   * wide as it is tall.
   *
   * @default "rectangle"
   */
  thumbShape?: SliderThumbShape;
  /**
   * Where the value is shown, or `none` to omit it.
   *
   * `top` is the resting readout beside the label. `start`/`end` put it on the track's own line,
   * which is what a thick track has room for. `bubble` moves it ONTO the thumb and hides the
   * resting one — the design shows a bubble or a readout, never both, so this is a placement
   * rather than a second value display.
   *
   * @default "top"
   */
  valuePlacement?: SliderValuePlacement;
  /**
   * Whether the readout is a read-only `<output>` or an editable `NumberField` per thumb.
   *
   * One field per thumb, derived rather than special-cased: a single slider gets one, a range gets
   * two, the same index mapping `thumbLabels` already uses.
   *
   * @default "output"
   */
  valueControl?: SliderValueControl;
  /**
   * What the resting readout says, given the values: a word for a value the number does not carry
   * (`모든 용량` for the whole range). The readout only; each thumb is still announced by its number
   * through `formatOptions`, so a screen reader hears the value it sets. Ignored by the `field`
   * control and the `bubble` placement, which show the number itself.
   */
  getValueLabel?: (values: number[]) => string;
  /**
   * Marks on the track. `true` draws one at every `step`; an array draws them at those values.
   *
   * `true` is refused above 50 marks rather than drawing a smear: a tick is a countable affordance,
   * and a `step` fine enough to exceed that is asking for a continuous track. Pass the array when
   * only some boundaries matter.
   */
  ticks?: boolean | number[];
  /**
   * Label under each tick. Off by default because a dense `step` overlaps them; pass a formatter
   * to control what each one says.
   */
  tickLabels?: boolean | ((value: number) => string);
  /**
   * Draw this slider's track inside a wider RULER, as `[from, to]`.
   *
   * The ruler is the axis the reader compares along; `minValue`/`maxValue` stay what they always
   * were — the values this slider can actually take — so the track becomes a span INSIDE the ruler
   * rather than the whole of it. A bar marks each end of that span.
   *
   * What it is for: a GROUP of sliders measuring one quantity with different permitted spans. Give
   * them the same `scale` and their thumbs land on one axis, so two rows can be read against each
   * other. Without it every track normalises to its own span and a thumb at 40% of one row means a
   * different number from a thumb at 40% of the next — which is exactly how a macro driving six
   * contrast floors reads as six unrelated movements.
   *
   * Nothing about behaviour changes, and that is the point of putting the ruler here rather than in
   * `minValue`: React Aria still owns the range, so the keyboard, the clamp and
   * `aria-valuemin`/`max` all describe what the reader can actually set. The ruler is drawn, never
   * enforced, and a value outside it is not representable because it is outside `minValue`/`maxValue`
   * too.
   *
   * Ignored when it does not contain the slider's own range.
   */
  scale?: [number, number];
  /** Slider label. */
  label?: string;
  /**
   * Helper text describing the control, wired to each thumb's `aria-describedby`.
   *
   * Every other form control in this library takes its description from React Aria's slot
   * mechanism (`<Text slot="description">`), which RAC wires into `aria-describedby` for free.
   * **`Slider` is the one that cannot**: its implementation provides no `TextContext` at all
   * (measured against the installed RAC, where `NumberField` provides one and `Slider` mentions
   * `description` zero times), so a `Text` slotted there would render and describe nothing. The
   * id is therefore generated and passed explicitly, and it goes on the THUMBS rather than the
   * root: the root is `role="group"` and the element carrying the slider role is the `<input>`
   * inside each thumb, which is what takes focus and what a screen reader reads from.
   */
  description?: string;
  /**
   * Why the current value is refused, shown under the control and wired into each thumb's (and each
   * value field's) `aria-describedby` after the `description`. Setting it marks every thumb and
   * value field invalid (`aria-invalid` on their inputs); clearing it clears that.
   *
   * A plain string, not the `(validation) => string` the other fields take: those come from React
   * Aria's form validation, which `Slider` has none of, for the same reason it has no `description`
   * slot. A consumer that refuses a value is the one that knows why, so it says so here.
   */
  errorMessage?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen. The label and the trigger share the label's
   * place in the header, so the value readout keeps its column.
   */
  contextualHelp?: ReactNode;
  /**
   * Accessible name per thumb, index-mapped (`[minimum, maximum]` for a range).
   *
   * Overrides {@link defaultThumbLabel} — the built-in `Minimum`/`Maximum` (+ `Value N` for a
   * middle thumb). Pass this to localize the handles or to name a domain-specific pair
   * (`["Check in", "Check out"]`). Each entry replaces exactly one thumb's `aria-label`, so a
   * shorter array leaves the remaining thumbs on their default. A single-thumb slider takes its
   * name from `label`, so it needs no entry — pass one only to override that.
   */
  thumbLabels?: string[];
  /** Additional class. sd-slider is always retained. */
  className?: string;
  /** Passed to the root slider DOM element. */
  ref?: Ref<HTMLDivElement>;
}

/** The track's place on the ruler, as `inset`/`size` percentages of the rail — or nothing, which
 *  is what renders the track exactly as it was before `scale` existed.
 *
 *  Defaults mirror React Aria's own (`0`/`100`) so a slider that states neither still resolves. */
function scaleOffsets(
  scale: [number, number] | undefined,
  minValue = 0,
  maxValue = 100,
  orientation = "horizontal",
): Record<string, string> | undefined {
  // Vertical is not refused so much as unwritten: the placement below is inline-axis, and a ruler
  // running down the page needs its own pair of declarations nobody has asked for yet.
  if (!scale || orientation !== "horizontal") return undefined;
  const [from, to] = scale;
  const span = to - from;
  // A ruler that does not contain the range would place the thumb off its own track.
  if (!(span > 0) || from > minValue || to < maxValue) return undefined;
  const size = ((maxValue - minValue) / span) * 100;
  // A zero-width band is KEPT, although a track with nothing to drag might seem to need no ruler: a
  // range pinned to one value is exactly when the reader needs the axis, because without it the
  // track springs back to full width and says the opposite of what is true.
  if (!(size >= 0)) return undefined;
  return {
    "--sd-slider-scale-inset": `${((minValue - from) / span) * 100}%`,
    "--sd-slider-scale-size": `${size}%`,
  };
}

/** Tick values for `ticks`, or `null` when there are too many to be countable. */
function tickValues(
  ticks: boolean | number[] | undefined,
  min: number,
  max: number,
  step: number,
): number[] | null {
  if (!ticks) return null;
  // The track's own ENDS already mark min and max, so a dot there is redundant and, being
  // centred on the boundary, half of it falls outside the track. The design draws them inset
  // for the same reason.
  if (Array.isArray(ticks)) return ticks.filter((v) => v > min && v < max);
  const span = max - min;
  if (!Number.isFinite(span) || step <= 0) return null;
  const count = Math.floor(span / step);
  // A tick is something a reader counts. Past this it is a texture, and the honest answer is to
  // say so rather than to paint 400 marks on a 320px track.
  if (count > 50) return null;
  return Array.from({ length: count + 1 }, (_, i) => min + i * step).filter((v) => v > min && v < max);
}

/**
 * Wraps the track in the RULER element when one resolves, and in nothing when it does not.
 *
 * A component rather than a ternary around the track so the track's own JSX stays where it is and
 * reads the same in both cases; and a real element rather than a pseudo-element because the track
 * has to be INSET inside the ruler, and React Aria maps the pointer through the track's own
 * `getBoundingClientRect()`.
 */
function SliderRuler({ offsets, children }: { offsets?: Record<string, string>; children: ReactNode }) {
  if (!offsets) return children;
  return (
    <div className="sd-slider__scale" style={offsets as CSSProperties}>
      {children}
    </div>
  );
}

/**
 * The editable readout: one `NumberField` per thumb.
 *
 * Reads `SliderStateContext` rather than a render prop, because it renders OUTSIDE `SliderTrack`
 * (which is where React Aria hands the state down) — the field sits beside the track, not in it.
 * React Aria exports the context for exactly this.
 *
 * Bounds and step come from the slider, never from props: a field that could be typed past the
 * track's own range would be a second, disagreeing source of truth for the same value.
 *
 * The accessible name is the SAME one the matching thumb takes, so the two never disagree — a
 * range gets `Minimum`/`Maximum` and a single-thumb slider takes the slider's own `label`. A
 * slider with neither `label` nor `thumbLabels` leaves both unnamed, which is the hole the thumbs
 * already have rather than a new one.
 *
 * `describedBy` is the thumbs' own `aria-describedby`, passed down rather than re-derived: a
 * reader who tabs into the field would otherwise miss the `description` the dragged thumb
 * announces, and the two readouts of one value must not describe it differently.
 */
function SliderValueFields({
  thumbLabels,
  label,
  describedBy,
  size,
  isInvalid,
}: {
  thumbLabels?: string[];
  label?: string;
  describedBy?: string;
  /** The slider's own size: the readout is the slider's value text, which follows `size` like a
   *  field's input (component-contract §7). */
  size: SliderSize;
  isInvalid?: boolean;
}) {
  const state = useContext(SliderStateContext);
  if (!state) return null;
  const count = state.values.length;
  return (
    <div className="sd-slider__fields" data-size={size}>
      {state.values.map((value, index) => (
        <NumberField
          key={index}
          size={size}
          isInvalid={isInvalid}
          className="sd-slider__field"
          aria-label={
            thumbLabels?.[index] ?? (count > 1 ? defaultThumbLabel(index, count) : label)
          }
          aria-describedby={describedBy}
          value={value}
          // An emptied field reports `NaN`, which is a keystroke rather than a value: React
          // Stately passes it through `snapValueToStep` unchanged, so the thumb's state becomes
          // NaN and the slider's own `onChange` hands NaN to the consumer: the fill freezes and
          // the range input reads 50, which is what a browser shows for an invalid value. Dropping it leaves the last good value
          // standing and `value` restores the text on blur.
          onChange={(next) => {
            if (!Number.isNaN(next)) state.setThumbValue(index, next);
          }}
          minValue={state.getThumbMinValue(index)}
          maxValue={state.getThumbMaxValue(index)}
          step={state.step}
          isDisabled={state.isDisabled}
        />
      ))}
    </div>
  );
}

export function Slider({
  size = "medium",
  isInset = false,
  thumbShape = "rectangle",
  valuePlacement = "top",
  valueControl = "output",
  getValueLabel,
  ticks,
  tickLabels,
  scale,
  label,
  description,
  errorMessage,
  contextualHelp,
  thumbLabels,
  className,
  ref,
  ...props
}: SliderProps) {
  const descriptionId = useId();
  const errorId = useId();
  const describedBy =
    [description && descriptionId, errorMessage && errorId].filter(Boolean).join(" ") || undefined;
  const ruler = scaleOffsets(scale, props.minValue, props.maxValue, props.orientation);
  return (
    <AriaSlider
      {...props}
      ref={ref}
      data-size={size}
      data-inset={isInset || undefined}
      data-thumb-shape={thumbShape}
      data-scale={ruler ? "" : undefined}
      data-value-placement={valuePlacement}
      className={className ? `sd-slider ${className}` : "sd-slider"}
    >
      {contextualHelp ? (
        <div className="sd-slider__label-group">
          {label && <Label className={`sd-slider__label sd-type-label-${size}`}>{label}</Label>}
          {contextualHelp}
        </div>
      ) : (
        label && <Label className={`sd-slider__label sd-type-label-${size}`}>{label}</Label>
      )}
      {(valuePlacement === "top" || valuePlacement === "start" || valuePlacement === "end") &&
        (valueControl === "field" ? (
          <SliderValueFields
            thumbLabels={thumbLabels}
            label={label}
            describedBy={describedBy}
            size={size}
            isInvalid={!!errorMessage}
          />
        ) : (
          <SliderOutput className={`sd-slider__output sd-type-body-${size}`}>
            {getValueLabel ? ({ state }) => getValueLabel(state.values) : undefined}
          </SliderOutput>
        ))}
      <SliderRuler offsets={ruler}>
        <SliderTrack className="sd-slider__track">
          {({ state }) => (
            <>
              {/* RAC spans the fill from the first thumb to the last for range values. */}
              <SliderFill className="sd-slider__fill" />
              {(() => {
                const marks = tickValues(ticks, state.getThumbMinValue(0), state.getThumbMaxValue(0), state.step);
                if (!marks) return null;
                const filled = state.getThumbPercent(state.values.length - 1);
                return marks.map((v) => {
                  const pct = state.getValuePercent(v);
                  return (
                    <span
                      key={v}
                      aria-hidden="true"
                      className="sd-slider__tick"
                      data-on-fill={pct <= filled || undefined}
                      style={{ "--sd-slider-tick-offset": `${pct * 100}%` } as CSSProperties}
                    >
                      {tickLabels && (
                        // CONTRASTIVE with the readout: the value the reader is SETTING is
                        // `body-<size>`, and a scale mark naming a boundary must not compete
                        // with it. One rung below the `caption-<size>` the description takes, for
                        // the same reason; `small` is the floor, so a small slider's marks share
                        // its description's rung.
                        <span className={`sd-slider__tick-label sd-type-caption-${TICK_RUNG[size]}`}>
                          {typeof tickLabels === "function" ? tickLabels(v) : v}
                        </span>
                      )}
                    </span>
                  );
                });
              })()}
              {valuePlacement === "bubble" && (
                <span
                  aria-hidden="true"
                  className={`sd-slider__bubble sd-type-body-${size}`}
                  style={{ "--sd-slider-bubble-offset": `${state.getThumbPercent(0) * 100}%` } as CSSProperties}
                >
                  {state.getFormattedValue(state.getThumbValue(0))}
                </span>
              )}
              {state.values.map((_, index) => (
                <SliderThumb
                  key={index}
                  index={index}
                  aria-label={
                    thumbLabels?.[index] ??
                    (state.values.length > 1
                      ? defaultThumbLabel(index, state.values.length)
                      : undefined)
                  }
                  aria-describedby={describedBy}
                  isInvalid={!!errorMessage}
                  className="sd-slider__thumb"
                />
              ))}
            </>
          )}
        </SliderTrack>
      </SliderRuler>
      {description && (
        <div id={descriptionId} className={`sd-slider__description sd-type-caption-${size}`}>
          {description}
        </div>
      )}
      {errorMessage && (
        <div id={errorId} className={`sd-slider__error sd-type-caption-${size}`}>
          {errorMessage}
        </div>
      )}
    </AriaSlider>
  );
}

.sd-slider {
  /* The readout over the track's end takes its END inset (rule 8); start/end placement re-set these. */
  --sd-slider-output-padding-start-current: 0px;
  --sd-slider-output-padding-end-current: var(--sd-slider-text-padding-inline);
  --sd-slider-display-current: grid;
  --sd-slider-grid-template-columns-current: 1fr auto;
  --sd-slider-flex-direction-current: row;
  --sd-slider-width-current: var(--sd-slider-width);
  --sd-slider-track-width-current: auto;
  --sd-slider-track-height-current: var(--sd-slider-track-thickness-current);
  --sd-slider-track-grid-column-current: 1 / -1;
  --sd-slider-label-grid-column-current: auto;
  --sd-slider-fill-width-current: auto;
  --sd-slider-fill-height-current: 100%;
  --sd-slider-thumb-top-current: 50%;
  --sd-slider-thumb-left-current: auto;
  /* The capsule's LONG axis runs along the track, so the two swap with orientation. */
  --sd-slider-thumb-inline-current: var(--sd-slider-thumb-long-current);
  --sd-slider-thumb-block-current: var(--sd-slider-thumb-short-current);

  /* Size axis. Declared here at the medium default rather than left `initial`, because every
     rule below reads them and a Slider with no `size` must still have a thickness. */
  --sd-slider-track-thickness-current: var(--sd-slider-track-height-medium);
  --sd-slider-thumb-long-current: var(--sd-slider-thumb-width-medium);
  --sd-slider-thumb-short-current: var(--sd-slider-thumb-height-medium);
  /* How far the thumb sticks out past the track on the CROSS axis. Anything placed beside the
     track has to clear this, not the track. */
  --sd-slider-thumb-overhang-current: calc(
    (var(--sd-slider-thumb-short-current) - var(--sd-slider-track-thickness-current)) / 2
  );

  /* How far the thumb's TRAVEL is pulled in from each end of the track. Without it the thumb is
     centred on its value, so at either extreme half of it hangs off the track: measured 18px on
     `size=medium` at both 0 and 100, and 8px on ColorSlider, which is exactly half a thumb.
     React Aria writes `left`/`top` and the `translate(-50%, -50%)` INLINE, so neither can be
     overridden from here and the only lever left is the containing block. An absolutely
     positioned child resolves its percentages against the PADDING box, which padding cannot
     shrink (it is part of that box) but a BORDER can, while `background` still paints the whole
     border box — so a transparent border of half a thumb on the track's long axis pulls the
     travel in and moves nothing that is drawn. */
  --sd-slider-travel-inset-current: calc(var(--sd-slider-thumb-long-current) / 2);
  --sd-slider-track-inset-inline-current: var(--sd-slider-travel-inset-current);
  --sd-slider-track-inset-block-current: 0px;
  /* How far the fill runs PAST the thumb's centre: nothing on a thin track, the thumb's half and
     the track's padding on an inset one (below), where the fill carries the thumb. */
  --sd-slider-fill-overrun-inline-current: 0px;
  --sd-slider-fill-overrun-block-current: 0px;
  /* The thumb's border width, relayed so an inset thumb can take its own. */
  --sd-slider-thumb-border-width-current: var(--sd-slider-thumb-border-width);

  display: var(--sd-slider-display-current);
  /* The label and the readout share a row, and the readout is the taller of the two — a `field` is
     a whole NumberField where the label is one line of text. Left to the grid's own default the
     label's glyphs sat at the TOP of the stretched row, measured 8px above the field's digits on a
     32px row, which reads as two things that were not laid out together. `start` and `end` already
     carried this declaration; `top`, the DEFAULT, did not, so two placements of three agreed and
     the third was the one everyone sees.
     A plain declaration with two overrides rather than a `-current` relay: rule 5 of
     `component-contract.md` §6 is for carrying a root STATE down to a child part, and both ends of
     this one are the root. */
  align-items: center;
  grid-template-columns: var(--sd-slider-grid-template-columns-current);
  flex-direction: var(--sd-slider-flex-direction-current);
  gap: var(--sd-slider-gap-medium);
  width: var(--sd-slider-width-current);
}

/* The gap closes up with the size, on the root and in the value fields the same. Each is
   declared per size outright on its own element (the fields carry `data-size` too), not relayed,
   so `spacing-relation:check` reads every rung. */
.sd-slider[data-size="small"] {
  gap: var(--sd-slider-gap-small);
  --sd-slider-track-thickness-current: var(--sd-slider-track-height-small);
  --sd-slider-thumb-long-current: var(--sd-slider-thumb-width-small);
  --sd-slider-thumb-short-current: var(--sd-slider-thumb-height-small);
}
.sd-slider[data-size="large"] {
  gap: var(--sd-slider-gap-large);
  --sd-slider-track-thickness-current: var(--sd-slider-track-height-large);
  --sd-slider-thumb-long-current: var(--sd-slider-thumb-width-large);
  --sd-slider-thumb-short-current: var(--sd-slider-thumb-height-large);
}

/* A circle thumb is as long as it is thick, at every size. Declared after the size rules, at their
   specificity, so it wins over each one's long axis. */
.sd-slider[data-thumb-shape="circle"] {
  --sd-slider-thumb-long-current: var(--sd-slider-thumb-short-current);
}

/* Inset: the thumb sits INSIDE the track, which grows to the thumb plus its padding on both sides,
   and the fill runs past the thumb to that padding so the filled part is one pill carrying it. The
   travel is pulled in by the padding too, so at either end the thumb keeps the same ring of track. */
.sd-slider[data-inset] {
  --sd-slider-inset-extent-current: calc(var(--sd-slider-thumb-short-current) + 2 * var(--sd-slider-track-padding));
  --sd-slider-track-thickness-current: var(--sd-slider-inset-extent-current);
  --sd-slider-travel-inset-current: calc(var(--sd-slider-thumb-long-current) / 2 + var(--sd-slider-track-padding));
  --sd-slider-fill-overrun-inline-current: var(--sd-slider-travel-inset-current);
  /* No ring: the fill always runs past an inset thumb, so the thumb sits on the brand fill alone, and
     white on that fill is the on-colour pairing the contrast contract already holds at 4.5:1. The
     ring the overhanging thumb needs against the pale track only ate into the thumb here. */
  --sd-slider-thumb-border-width-current: 0px;
}

.sd-slider[data-orientation="vertical"] {
  /* Stacked under the label, the readout starts on the label's text line rather than ending on the
     track's (rule 8); the two-attribute rule after the placement block holds it for every placement. */
  --sd-slider-output-padding-start-current: var(--sd-slider-text-padding-inline);
  --sd-slider-output-padding-end-current: 0px;
  --sd-slider-display-current: flex;
  /* A flex COLUMN, so `align-items` is the inline axis here rather than the block one. Centring is
     the answer for the row shape above; vertically it would pull the track off the inline start it
     sits on, so the initial value is restored. */
  align-items: normal;
  --sd-slider-grid-template-columns-current: none;
  --sd-slider-flex-direction-current: column;
  --sd-slider-width-current: auto;
  --sd-slider-track-width-current: var(--sd-slider-track-thickness-current);
  --sd-slider-track-height-current: var(--sd-slider-track-length);
  --sd-slider-track-grid-column-current: auto;
  --sd-slider-fill-width-current: 100%;
  --sd-slider-fill-height-current: auto;
  --sd-slider-thumb-top-current: auto;
  --sd-slider-thumb-left-current: 50%;
  /* Long axis along the track again, which vertically means tall rather than wide. */
  --sd-slider-thumb-inline-current: var(--sd-slider-thumb-short-current);
  --sd-slider-thumb-block-current: var(--sd-slider-thumb-long-current);
  /* and so the travel inset swaps with it */
  --sd-slider-track-inset-inline-current: 0px;
  --sd-slider-track-inset-block-current: calc(var(--sd-slider-thumb-long-current) / 2);
}
/* Vertical and inset: the travel and the overrun move to the block axis with the track. */
.sd-slider[data-orientation="vertical"][data-inset] {
  --sd-slider-track-inset-block-current: var(--sd-slider-travel-inset-current);
  --sd-slider-fill-overrun-inline-current: 0px;
  --sd-slider-fill-overrun-block-current: var(--sd-slider-travel-inset-current);
}

/* Disabled: dim the whole control uniformly at the root (RAC emits data-disabled here) so
   track/fill/label/output all read as disabled — not just the thumb. */
.sd-slider[data-disabled] {
  opacity: var(--sd-state-disabled);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger take the label's
   grid cell together, so the readout keeps column 2 and the header row keeps its shape. */
.sd-slider__label-group {
  grid-column: var(--sd-slider-label-grid-column-current);
  display: flex;
  align-items: center;
  gap: var(--sd-slider-label-group-gap);
  min-inline-size: 0;
}

/* The label and the description stand on the text line with every other field's label
   (component-contract.md §6 rule 8). */
.sd-slider__label {
  grid-column: var(--sd-slider-label-grid-column-current);
  color: var(--sd-slider-label-foreground);
  padding-inline-start: var(--sd-slider-text-padding-inline);
  /* Centring the row sizes every item to its content, which would shrink the label from the row's
     full height to its own line box — 32px to 17.5px beside a `field`. Clicking a label focuses the
     slider, so that is a target getting smaller for a purely visual fix. Stretching the BOX back
     and centring the TEXT inside it keeps both. */
  align-self: stretch;
  display: flex;
  align-items: center;
}

.sd-slider__output {
  color: var(--sd-slider-output-foreground);
  font-variant-numeric: tabular-nums;
  /* On the text line, on the side it shares with the track (rule 8): its end when it sits over the
     track's end, its start when it leads the track. Relayed from the root by placement (§6 rule 5). */
  padding-inline-start: var(--sd-slider-output-padding-start-current);
  padding-inline-end: var(--sd-slider-output-padding-end-current);
}

/* The editable readout. One field per thumb, so a range lays two side by side in the slot the
   single `output` would have taken; the gap is the slider's own so the pair reads as one control. */
/* One field per thumb, so a RANGE renders two. Capped at one field wide and allowed to wrap, which
   stacks the pair instead of laying them side by side: two 7rem fields plus a gap in one `auto`
   column left a 320px track with 80px, measured, and the track is the control. Flanking them
   (minimum at the start, maximum at the end) reads better and is the open question here — it needs
   the two fields to be separate grid items, which is a `display: contents` trick or a second
   container, and neither is worth the cleverness before someone asks for a typed range. */
.sd-slider__fields {
  --sd-slider-field-current: var(--sd-slider-field-medium);
  display: flex;
  flex-wrap: wrap;
  max-width: var(--sd-slider-field-current);
  gap: var(--sd-slider-gap-medium);
  align-items: center;
}
/* The field's width follows the size with its stepper pair (`slider.field.<size>`), relayed to each
   field from this wrapper, the element that carries `data-size`. */
.sd-slider__fields[data-size="small"] {
  --sd-slider-field-current: var(--sd-slider-field-small);
  gap: var(--sd-slider-gap-small);
}
.sd-slider__fields[data-size="large"] {
  --sd-slider-field-current: var(--sd-slider-field-large);
  gap: var(--sd-slider-gap-large);
}
.sd-slider__field {
  width: var(--sd-slider-field-current);
}

/* ── `scale`: the track is a SPAN inside a wider ruler ─────────────────────────────────
   Defaults that resolve to exactly what the track always was, so a slider stating no `scale` pays
   nothing for any of this and needs no state attribute to say so: the ruler ELEMENT is the switch,
   and it is rendered only when a ruler resolves. */
.sd-slider {
  --sd-slider-scale-inset: 0%;
  --sd-slider-scale-size: var(--sd-slider-track-width-current);
}
.sd-slider[data-scale] {
  --sd-slider-track-inset-inline-current: 0px;
}

/* The ruler: the axis the reader compares along, wider than this slider's own track. It is a real
   element and not a pseudo-element on the track, because the track has to be INSET inside it —
   React Aria maps the pointer through the track's own `getBoundingClientRect()`, so a track drawn
   narrower than it measures would drag to the wrong value. */
.sd-slider__scale {
  position: relative;
  grid-column: var(--sd-slider-track-grid-column-current);
  width: var(--sd-slider-track-width-current);
  height: var(--sd-slider-track-height-current);
  background: var(--sd-slider-track-background);
  border-radius: var(--sd-slider-track-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* Transparent on purpose, exactly as on a plain track: the thumb's travel, pulled in once from
     the shared axis. `background` still paints the whole border box, so the ruler reads full width
     while every row's percentages resolve against the same inner span.
     Taking the inset off the track here — by inheritance, which is why no descendant combinator is
     needed — is what makes the shared axis EXACT rather than approximate. Left on the track, each
     row insets by half its own thumb inside a span of its own width, so one value lands at a
     different x on every row: measured 18px apart for `9` across two rows of one scale, which is
     the whole claim of the feature. A thumb may now overhang its own band, and that is correct —
     it is still inside the ruler, which is where the numbers are.
     The other half of the transfer — zeroing the track's own inset — is the `[data-scale]` rule
     above rather than an inherited `0px` here, which is where it was first written. Two
     UNCONDITIONAL declarations of one `-current` relay are a shape `build-binding-manifests.mjs`
     refuses to emit: it cannot scope the `else` branch, so both Slider rows reading that relay
     would enter the Figma binding manifest asserting nothing. A `data-*` condition is what the
     parser can scope, and it is what `component-contract.md` §6 rule 3 asks for anyway. */
  border-inline: var(--sd-slider-travel-inset-current) solid transparent;
}

/* The two ends of the adjustable span, as one box drawn on the ruler with only its side borders.
   Both offsets are percentages of the ruler's padding box — the same basis the track is placed
   against — so the bars sit exactly on the track's ends without either element measuring the other.
   Bars rather than `tick` dots: a tick is a step you count, and `tickValues` drops the endpoint ones
   because the track's own ends already mark them. On a ruler the track no longer ends where the axis
   does, so the boundary needs a mark of its own, and it says bracketed rather than stepped. */
.sd-slider__scale::after {
  content: "";
  position: absolute;
  inset-inline: var(--sd-slider-scale-inset)
    calc(100% - var(--sd-slider-scale-inset) - var(--sd-slider-scale-size));
  inset-block: calc(-1 * var(--sd-slider-scale-mark-overhang));
  border-inline: var(--sd-slider-scale-mark-width) solid var(--sd-slider-scale-mark-background);
  pointer-events: none;
}

.sd-slider__track {
  position: relative;
  grid-column: var(--sd-slider-track-grid-column-current);
  /* Percentages resolve against the containing block, which is the ruler when `scale` gave the
     track one and the grid column when it did not — so one pair of declarations covers both, and
     the defaults above make the unscaled case identical to the plain `width` this replaced. */
  margin-inline-start: var(--sd-slider-scale-inset);
  inline-size: var(--sd-slider-scale-size);
  height: var(--sd-slider-track-height-current);
  background: var(--sd-slider-track-background);
  border-radius: var(--sd-slider-track-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* Not chrome: this is the thumb's travel inset, and it is transparent on purpose. */
  border-inline: var(--sd-slider-track-inset-inline-current) solid transparent;
  border-block: var(--sd-slider-track-inset-block-current) solid transparent;
}

.sd-slider__fill {
  width: var(--sd-slider-fill-width-current);
  height: var(--sd-slider-fill-height-current);
  background: var(--sd-slider-fill-background);
  border-radius: var(--sd-slider-fill-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* The fill is anchored to the track's leading edge and sized as a percentage, so the travel
     inset on the track moves BOTH of its ends inward. Each end needs its own correction and they
     are not the same correction:
       the ANCHORED end is pulled back out with a negative margin, so the fill still starts at the
         visual end of the track rather than a half-thumb inside it;
       the VALUE end is pushed back out with padding, because what the fill's end means is the
         value, and the value is the thumb's CENTRE. `box-sizing: content-box` is what makes the
         padding ADD to the width react-aria writes inline rather than eat into it.
     Shipping only the first correction, which is what 21d2daa did, leaves the fill ending at the
     thumb's leading EDGE — a visible half-thumb short of the value on any thumb you can see
     through, and the owner caught it on a dark-theme capsule. "Where a fill is supposed to stop"
     was asserted in that commit message and never measured; it stops at the centre. */
  box-sizing: content-box;
  margin-inline-start: calc(-1 * var(--sd-slider-track-inset-inline-current));
  padding-inline-end: calc(var(--sd-slider-track-inset-inline-current) + var(--sd-slider-fill-overrun-inline-current));
  margin-block-end: calc(-1 * var(--sd-slider-track-inset-block-current));
  padding-block-start: calc(var(--sd-slider-track-inset-block-current) + var(--sd-slider-fill-overrun-block-current));
}

.sd-slider__thumb {
  /* The one stacking declaration in this file, and it exists for exactly one overlap. Everything
     inside the track already paints in DOM order with the thumb last, so it needs no lift there;
     what sits above it is `.sd-slider__scale::after`, a generated LAST child of the ruler and
     therefore later than the whole track. At either end of the adjustable range the thumb's centre
     IS the bound mark, so the bar would paint a stripe down the middle of the thumb and through its
     focus ring.
     The lift goes here rather than on the mark: `z-index: -1` there would put the bar behind the
     ruler's own background (neither box opens a stacking context) and delete it, and lifting the
     TRACK instead would hide the bars everywhere they cross it, which is most of their length. */
  z-index: 1;
  /* RAC sets the position axis inline (left horizontally, top vertically) plus the
     translate; the local intermediates center only the cross axis. */
  top: var(--sd-slider-thumb-top-current);
  left: var(--sd-slider-thumb-left-current);
  width: var(--sd-slider-thumb-inline-current);
  height: var(--sd-slider-thumb-block-current);
  background: var(--sd-slider-thumb-background);
  border: var(--sd-slider-thumb-border-width-current) solid var(--sd-slider-thumb-border);
  border-radius: var(--sd-slider-thumb-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  box-shadow: var(--sd-slider-thumb-shadow);
  cursor: grab;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  outline: none;
}
.sd-slider__thumb[data-hovered] {
  box-shadow: var(--sd-slider-thumb-shadow-hover);
}
.sd-slider__thumb[data-dragging] {
  cursor: grabbing;
  /* NOT transform:scale — react-aria sets the thumb's transform inline (translate for
     positioning), which overrides a stylesheet transform. Use a halo box-shadow instead. */
  box-shadow: var(--sd-slider-thumb-shadow-dragging);
}
.sd-slider__thumb[data-focus-visible] {
  box-shadow: var(--sd-slider-thumb-shadow), 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-slider__thumb[data-disabled] {
  /* Opacity is applied once at the root (.sd-slider[data-disabled]) to avoid double-dimming;
     the thumb only needs the not-allowed cursor. */
  cursor: not-allowed;
}

/* Spans both columns like the track, because it describes the control rather than the label it
   sits beside. `grid-column` is inert in the vertical case, where the root is a flex column and
   this is simply the last child. */
.sd-slider__description,
.sd-slider__error {
  grid-column: 1 / -1;
  padding-inline-start: var(--sd-slider-text-padding-inline);
}
.sd-slider__description {
  color: var(--sd-slider-description-foreground);
}
.sd-slider__error {
  color: var(--sd-slider-error-foreground);
}

/* ── Ticks ────────────────────────────────────────────────────────────────────────────────────
   Positioned along the track by percentage, centred with the INDEPENDENT `translate` property
   rather than inside a `transform`: the thumb beside them proves why (component-contract § 6
   rule 6 — a state transform would replace a positioning one). `--sd-slider-tick-offset` is a
   local intermediate the component sets inline, not a token, so it is declared here. */
.sd-slider__tick {
  --sd-slider-tick-offset: 0%;

  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: var(--sd-slider-tick-offset);
  translate: -50% -50%;
  width: var(--sd-slider-tick-size);
  height: var(--sd-slider-tick-size);
  border-radius: var(--sd-slider-tick-radius);
  corner-shape: round;
  background: var(--sd-slider-tick-background);
  pointer-events: none;
}
/* A tick under the fill has to read against it, not against the empty track. */
.sd-slider__tick[data-on-fill] {
  background: var(--sd-slider-tick-background-on-fill);
}
.sd-slider[data-orientation="vertical"] .sd-slider__tick {
  /* From the block END, not the start: a vertical slider's zero is at the BOTTOM, which the fill
     already shows, so measuring from the top renders the scale upside down (value 25 lands where 75
     belongs). */
  inset-block-start: auto;
  inset-block-end: var(--sd-slider-tick-offset);
  inset-inline-start: 50%;
  translate: -50% 50%;
}

.sd-slider__tick-label {
  position: absolute;
  inset-block-start: calc(100% + var(--sd-slider-tick-label-gap));
  inset-inline-start: 50%;
  translate: -50% 0;
  color: var(--sd-slider-tick-label-foreground);
  white-space: nowrap;
}

/* ── Value bubble ─────────────────────────────────────────────────────────────────────────────
   Rides the thumb and REPLACES the resting readout — the two are placements of one value, so a
   slider never shows both. `aria-hidden`, because the thumb already reports the value through
   its own `aria-valuetext`; a second announcement would double it. */
.sd-slider__bubble {
  --sd-slider-bubble-offset: 0%;

  position: absolute;
  inset-block-end: calc(100% + var(--sd-slider-bubble-gap));
  inset-inline-start: var(--sd-slider-bubble-offset);
  translate: -50% 0;
  padding: var(--sd-slider-bubble-padding-block) var(--sd-slider-bubble-padding-inline);
  color: var(--sd-slider-bubble-foreground);
  background: var(--sd-slider-bubble-background);
  border: var(--sd-slider-bubble-border-width) solid var(--sd-slider-bubble-border);
  border-radius: var(--sd-slider-bubble-radius);
  corner-shape: round;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  pointer-events: none;
}
/* The arrow is the bubble's own bottom corner, rotated — one element, so it cannot drift from
   the bubble it belongs to, and it inherits the border and background rather than restating them. */
.sd-slider__bubble::after {
  content: "";
  position: absolute;
  inset-block-start: 100%;
  inset-inline-start: 50%;
  translate: -50% -50%;
  rotate: 45deg;
  width: var(--sd-slider-bubble-arrow-size);
  height: var(--sd-slider-bubble-arrow-size);
  background: var(--sd-slider-bubble-background);
  border-inline-end: var(--sd-slider-bubble-border-width) solid var(--sd-slider-bubble-border);
  border-block-end: var(--sd-slider-bubble-border-width) solid var(--sd-slider-bubble-border);
}

/* ── Value placement ──────────────────────────────────────────────────────────────────────────
   `top` is the default grid: label and readout share row 1, the track spans row 2. `start`/`end`
   put the readout on the TRACK's row instead, which is the arrangement a thick track has room
   for, so the root becomes three columns and the track stops spanning them. */
.sd-slider[data-value-placement="start"],
.sd-slider[data-value-placement="end"] {
  --sd-slider-grid-template-columns-current: auto 1fr auto;
  --sd-slider-track-grid-column-current: 2;
  /* The label row spans all three columns, read by `__label` and `__label-group` below. */
  --sd-slider-label-grid-column-current: 1 / -1;
  /* Kept, and not redundant with the base declaration: it is what centres the VERTICAL start/end
     shape, which the `[data-orientation]` rule above sets back to `normal`. Equal specificity and
     later in the file, so it wins for both orientations — which is exactly what it did before the
     base gained its own. Deleting it on the reasoning that the base now covers it was measured
     wrong by a cold read the same day. */
  align-items: center;
}
/* On the track's row the readout faces the track on one side and the field edge on the other, so
   each placement states its own pair once. One shared rule with `end` overriding it reads the same
   in a browser but puts the projection reader on the wrong branch. */
.sd-slider[data-value-placement="start"] {
  --sd-slider-output-padding-start-current: var(--sd-slider-text-padding-inline);
  --sd-slider-output-padding-end-current: 0px;
}
.sd-slider[data-value-placement="start"] .sd-slider__output,
.sd-slider[data-value-placement="start"] .sd-slider__fields {
  grid-column: 1;
  grid-row: 2;
}
.sd-slider[data-value-placement="end"] {
  --sd-slider-output-padding-start-current: 0px;
  --sd-slider-output-padding-end-current: var(--sd-slider-text-padding-inline);
}
.sd-slider[data-value-placement="end"] .sd-slider__output,
.sd-slider[data-value-placement="end"] .sd-slider__fields {
  grid-column: 3;
  grid-row: 2;
}
/* Vertical, every placement stacks the readout in the column with the label, so it starts on the
   label's text line. Two attributes, so it outranks the placement relays above whatever their order. */
.sd-slider[data-orientation="vertical"][data-value-placement] {
  --sd-slider-output-padding-start-current: var(--sd-slider-text-padding-inline);
  --sd-slider-output-padding-end-current: 0px;
}


/* Vertically the label cannot sit BELOW its tick — that is on the track. It goes beside it, on the
   track's inline end, centred on the mark it names. Caught by the coverage gap the engine reported
   for the vertical tick rule, which had no story and therefore no render anyone had looked at. */
.sd-slider[data-orientation="vertical"] .sd-slider__tick-label {
  inset-block-start: 50%;
  /* Clears the THUMB, not the track: the thumb is wider than the track it rides, so a gap measured
     from the track's edge still lands under it. Same shape as the label/thumb collision on
     ColorSlider earlier the same day. */
  inset-inline-start: calc(100% + var(--sd-slider-tick-label-gap) + max(0px, var(--sd-slider-thumb-overhang-current)));
  translate: 0 -50%;
}
